// A caller's bug whatever the schema says: no provider hands the model's arguments over as anything but an object.
function malformedInput(name: string, kind: string): TypeError {
  return new TypeError(`Tool '${name.slice(0, MAX_NAME_IN_ANSWER)}' needs an object as input, and got ${kind}`);
}
</document>
<document source="src/orchestration/tools/registry.test.ts" type="test" relevance="0.53" tokens="163">
// One registered tool whose executor throws `thrown`, whatever its shape.
function throwing(name: string, thrown: unknown): ToolRegistry {
  const registry = new ToolRegistry();
  registry.register({name, description: `The ${name} tool.`, inputSchema: {type: 'object'}}, async () => {
    throw thrown;
  });
  return registry;
}

// One registered tool per name, each answering 'ok'.
function registryWith(...names: string[]): ToolRegistry {
  const registry = new ToolRegistry();
  for (const name of names) {
    registry.register({name, description: `The ${name} tool.`, inputSchema: {type: 'object'}}, async () => 'ok');
  }
  return registry;
}
</document>
