import Ajv, {type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
  dynamicValidators?: WeakMap<object, ValidateFunction>;
}

const ajv = new Ajv({strict: false, validateFormats: false} as ConstructorParameters<typeof Ajv>[0]);

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validator = ajv.compile(resolved.inputSchema);
      } catch (error) {
        const reason = error instanceof Error ? error.message : String(error);
        throw new Error(`Invalid inputSchema for tool '${resolved.name}': ${reason}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {
      definitionSource: definition,
      execute,
      validator,
      dynamicValidators: typeof definition === 'function' ? new WeakMap() : undefined,
    });
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input and returns schema rejections as ToolResponses; only unknown tools throw (see specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    let validator = tool.validator;
    if (!validator) {
      const cached = tool.dynamicValidators?.get(definition.inputSchema);
      validator = cached ?? ajv.compile(definition.inputSchema);
      tool.dynamicValidators?.set(definition.inputSchema, validator);
    }
    return this.executeWithValidator(tool, definition, validator, name, input, context);
  }

  private async executeWithValidator(
    tool: StoredTool,
    definition: ToolDefinition,
    validator: ValidateFunction,
    name: string,
    input: Record<string, unknown>,
    context?: ToolContext
  ): Promise<ToolResponse> {
    if (validator(input)) {
      log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
      const rawResult = await tool.execute(input, context);
      const response = normalizeToolResponse(rawResult);
      log.info('tool', 'execution complete', {
        name,
        rawType: typeof rawResult,
        clientMessageCount: response.clientMessages?.length ?? 0,
        clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
        suppressAssistantResponse: response.suppressAssistantResponse ?? false,
      });
      return response;
    }
    const error = validator.errors?.[0];
    const missingProperty = error && 'missingProperty' in error.params ? error.params.missingProperty : undefined;
    const instancePath =
      error && 'instancePath' in error && typeof error.instancePath === 'string' ? error.instancePath : undefined;
    const path = missingProperty ? `${instancePath || ''}/${missingProperty}` : instancePath || '(root)';
    const message = error?.message ?? 'is invalid';
    log.warn('tool', 'input validation failed', {name, path, message});
    return {result: `Tool '${definition.name}' input invalid: ${path} ${message}`};
  }
}
import Ajv from 'ajv';
import {jest} from '@jest/globals';
import {setLogger} from '../../shared/logger.js';
import {ToolRegistry} from './registry.js';

const executeTenTimes = (registry: ToolRegistry, input: Record<string, unknown>): Promise<unknown[]> =>
  Promise.all(Array.from({length: 10}, () => registry.execute('weather', input)));

describe('ToolRegistry', () => {
  it('compiles a static schema once across repeated executions', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}},
      },
      async () => 'sunny'
    );

    await executeTenTimes(registry, {location: 'Paris'});

    expect(compile).toHaveBeenCalledTimes(1);
    compile.mockRestore();
  });

  it('rejects a wrong-typed property with its field and expected type without leaking its value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'ssn_lookup',
        description: 'Look up a record by identifier',
        inputSchema: {
          type: 'object',
          properties: {ssn: {type: 'string'}},
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('ssn_lookup', {ssn: 123456789});

    expect({executorCalls, result: response.result, leaksValue: response.result.includes('123456789')}).toEqual({
      executorCalls: 0,
      result: expect.stringMatching(/ssn.*string/i),
      leaksValue: false,
    });
  });

  it('names the complete nested path when a required property is missing', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'nested_weather',
        description: 'Get nested weather data',
        inputSchema: {
          type: 'object',
          properties: {
            location: {
              type: 'object',
              properties: {city: {type: 'string'}},
              required: ['city'],
            },
          },
          required: ['location'],
        },
      },
      async () => 'sunny'
    );

    const response = await registry.execute('nested_weather', {location: {}});

    expect(response.result).toMatch(/\/location.*city.*required/i);
  });

  it('logs the rejected field and constraint without logging its value', async () => {
    const logLines: string[] = [];
    const logger = {
      debug: (_category: string, message: string, fields?: Record<string, unknown>) =>
        logLines.push(JSON.stringify({message, fields})),
      info: (_category: string, message: string, fields?: Record<string, unknown>) =>
        logLines.push(JSON.stringify({message, fields})),
      warn: (_category: string, message: string, fields?: Record<string, unknown>) =>
        logLines.push(JSON.stringify({message, fields})),
      error: (_category: string, message: string, fields?: Record<string, unknown>) =>
        logLines.push(JSON.stringify({message, fields})),
    };
    setLogger(logger);
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'ssn_lookup',
        description: 'Look up a record',
        inputSchema: {type: 'object', properties: {ssn: {type: 'string'}}},
      },
      async () => 'found'
    );

    await registry.execute('ssn_lookup', {ssn: 123456789});

    expect({
      hasPathAndConstraint: logLines.some(line => line.includes('ssn') && line.includes('string')),
      leaksValue: logLines.some(line => line.includes('123456789')),
    }).toEqual({hasPathAndConstraint: true, leaksValue: false});
    setLogger(undefined);
  });

  it('passes valid input with undeclared properties through unchanged', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Paris', requestId: 'req-123'};
    const executorInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async receivedInput => {
        executorInputs.push(receivedInput);
        return 'sunny';
      }
    );

    await registry.execute('weather', input);

    expect(executorInputs).toEqual([input]);
  });

  it('compiles a function-valued schema once per schema object across repeated executions', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    const schema = {type: 'object', properties: {location: {type: 'string'}}};
    registry.register(
      () => ({name: 'weather', description: 'Get weather', inputSchema: schema}),
      async () => 'sunny'
    );

    await executeTenTimes(registry, {location: 'Paris'});

    expect(compile).toHaveBeenCalledTimes(1);
    compile.mockRestore();
  });

  it('throws at register time naming the tool when a static schema cannot be compiled', () => {
    const registry = new ToolRegistry();
    const brokenDefinition = {
      name: 'broken_weather',
      description: 'Has an invalid JSON Schema type',
      inputSchema: {
        type: 'object',
        properties: {location: {type: 'not-a-json-schema-type'}},
      },
    };

    expect(() => registry.register(brokenDefinition, async () => 'unreachable')).toThrow(
      /Invalid inputSchema for tool 'broken_weather'/
    );
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When a nested object omits a property listed in its `required` array, the rejection names the complete failing property path ([validated by: names the complete nested path when a required property is missing](../../src/orchestration/tools/registry.test.ts#L55)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46), [validated by: rejects a wrong-typed property with its field and expected type without leaking its value](../../src/orchestration/tools/registry.test.ts#L28), [validated by: logs the rejected field and constraint without logging its value](../../src/orchestration/tools/registry.test.ts#L81)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults ([validated by: passes valid input with undeclared properties through unchanged](../../src/orchestration/tools/registry.test.ts#L113)).
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94), [validated by: throws at register time naming the tool when a static schema cannot be compiled](../../src/orchestration/tools/registry.test.ts#L153)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by: compiles a static schema once across repeated executions](../../src/orchestration/tools/registry.test.ts#L10)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: compiles a function-valued schema once per schema object across repeated executions](../../src/orchestration/tools/registry.test.ts#L138)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: feeds a rejected tool call back to the provider so a corrected retry can resolve](../../src/orchestration/chatOrchestrator.test.ts#L401), [validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
